/* Card set: Dinosaurs (generated from the approved roster.csv by the Dinosaurs build, schema per tools/csv-to-set.js).
   (dinosaurs.js exceeds the comfortable push size, so the remaining cards live in
   dinosaurs-additions.js, which must stay directly after 'dinosaurs.js' in sets/manifest.js.) */
CardSets.register({"id":"dinosaurs","name":"Dinosaurs","code":"DINO","description":"420 cards from the age of reptiles — the great theropod hunters, long-necked sauropods, horned and armoured giants, the reptiles of sea and sky, and the famous fossils that brought them back.","theme":{"primary":"#4e7a3d","secondary":"#37474f","artBackground":"#eef0e4","artFit":"contain"},"pack":{"name":"Dinosaur Pack","emblem":"🦖","skin":"dinosaurs"},"cards":[{"name":"Tyrannosaurus rex","rarity":"chase","id":"tyrannosaurus-rex","subtitle":"Theropod","details":"A massive tyrannosaurid from Late Cretaceous western North America, T. rex combined binocular vision with a bone-crushing bite, the strongest of any land animal.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/Tyrannosaurus_TD.png/1280px-Tyrannosaurus_TD.png"},{"name":"Velociraptor","rarity":"chase","id":"velociraptor","subtitle":"Theropod","details":"A small feathered raptor from Late Cretaceous Mongolia, Velociraptor hunted with an enlarged, retractable sickle claw raised on each hind foot as it ran.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Velociraptor_TD.png/1280px-Velociraptor_TD.png"},{"name":"Spinosaurus","rarity":"chase","id":"spinosaurus","subtitle":"Theropod","details":"A sail-backed fish-eater from mid-Cretaceous North Africa, Spinosaurus carried a long, crocodile-like snout lined with conical teeth for gripping slippery prey.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Spinosaurus_TD.png/1280px-Spinosaurus_TD.png"},{"name":"Allosaurus","rarity":"chase","id":"allosaurus","subtitle":"Theropod","details":"The apex predator of the Late Jurassic Morrison Formation in western North America, Allosaurus bore low bony ridges above its eyes and grew over 8 metres long.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Allosaurus_TD.png/1280px-Allosaurus_TD.png"},{"name":"Giganotosaurus","rarity":"chase","id":"giganotosaurus","subtitle":"Theropod","details":"A giant carcharodontosaurid from Late Cretaceous Argentina, Giganotosaurus ranks among the largest land predators known, rivalling T. rex in overall size.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/Giganotosaurus_TD.png/1280px-Giganotosaurus_TD.png"},{"name":"Carcharodontosaurus","rarity":"legendary","id":"carcharodontosaurus","subtitle":"Theropod","details":"A giant predator from mid-to-Late Cretaceous North Africa, Carcharodontosaurus was named for its shark-like, finely serrated teeth, shaped for slicing flesh.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Carcharodontosaurus_TD.png/1280px-Carcharodontosaurus_TD.png"},{"name":"Deinonychus","rarity":"legendary","id":"deinonychus","subtitle":"Theropod","details":"A sickle-clawed hunter from Early Cretaceous North America, Deinonychus was an agile, warm-blooded predator whose discovery helped spark the dinosaur renaissance.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Deinonychus_TD.png/1280px-Deinonychus_TD.png"},{"name":"Dilophosaurus","rarity":"legendary","id":"dilophosaurus","subtitle":"Theropod","details":"An early predator from Early Jurassic North America, Dilophosaurus carried a pair of thin, semicircular crests on its head, likely used for display to its kind.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Dilophosaurus_TD.png/1280px-Dilophosaurus_TD.png"},{"name":"Carnotaurus","rarity":"legendary","id":"carnotaurus","subtitle":"Theropod","details":"A horned abelisaur from Late Cretaceous Argentina, Carnotaurus had a bull-like skull, two brow horns and extremely short arms, among the tiniest of any large theropod.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Carnotaurus_TD.png/1280px-Carnotaurus_TD.png"},{"name":"Utahraptor","rarity":"legendary","id":"utahraptor","subtitle":"Theropod","details":"The largest known dromaeosaur, this Early Cretaceous North American raptor stood far taller than its kin and wielded a huge curved claw on each hind foot.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Utahraptor_Restoration.png/500px-Utahraptor_Restoration.png"},{"name":"Acrocanthosaurus","rarity":"legendary","id":"acrocanthosaurus","subtitle":"Theropod","details":"A ridge-backed giant allosauroid from Early Cretaceous Oklahoma and Texas, Acrocanthosaurus was the largest predator of its time in North America.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Acrocanthosaurus_TD.png/1280px-Acrocanthosaurus_TD.png"},{"name":"Tarbosaurus","rarity":"legendary","id":"tarbosaurus","subtitle":"Theropod","details":"A close Asian relative of T. rex from Late Cretaceous Mongolia, Tarbosaurus had a narrower skull and tiny two-fingered hands, and hunted giant hadrosaurs.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/Tarbosaurus_TD.png/1280px-Tarbosaurus_TD.png"},{"name":"Therizinosaurus","rarity":"legendary","id":"therizinosaurus","subtitle":"Theropod","details":"A pot-bellied plant-eater from Late Cretaceous Mongolia, Therizinosaurus was armed with enormous scythe-like hand claws, the longest claws of any known animal.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/Therizinosaurus_TD.png/1280px-Therizinosaurus_TD.png"},{"name":"Deinocheirus","rarity":"epic","id":"deinocheirus","subtitle":"Theropod","details":"A hump-backed ostrich mimic from Late Cretaceous Mongolia, Deinocheirus combined huge arms and blunt claws with a broad, toothless, duck-like bill for cropping plants.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Deinocheirus_TD.png/1280px-Deinocheirus_TD.png"},{"name":"Baryonyx","rarity":"epic","id":"baryonyx","subtitle":"Theropod","details":"A fish-eating spinosaur from Early Cretaceous England, Baryonyx snatched prey from rivers with a crocodile-like snout and a giant claw on each thumb.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Baryonyx_TD.png/1280px-Baryonyx_TD.png"},{"name":"Suchomimus","rarity":"epic","id":"suchomimus","subtitle":"Theropod","details":"A sail-backed fish-eater from Early Cretaceous Niger, Suchomimus means 'crocodile mimic', a nod to its long, low snout filled with over a hundred teeth.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Suchomimus_paleoart_2024.png/1280px-Suchomimus_paleoart_2024.png"},{"name":"Megalosaurus","rarity":"epic","id":"megalosaurus","subtitle":"Theropod","details":"From Middle Jurassic England, Megalosaurus was the first dinosaur genus ever formally named, described in 1824, decades before the word dinosaur existed.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Megalosaurus_TD.png/1280px-Megalosaurus_TD.png"},{"name":"Ceratosaurus","rarity":"epic","id":"ceratosaurus","subtitle":"Theropod","details":"A predatory theropod from Late Jurassic North America, Ceratosaurus is recognised by the distinctive horn on its nose and a row of small bony plates down its back.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Ceratosaurus_TD.png/1280px-Ceratosaurus_TD.png"},{"name":"Majungasaurus","rarity":"epic","id":"majungasaurus","subtitle":"Theropod","details":"A stocky abelisaur from Late Cretaceous Madagascar, Majungasaurus left bite marks on its own kind, giving direct fossil evidence of cannibalism in dinosaurs.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Majungasaurus_TD.png/1280px-Majungasaurus_TD.png"},{"name":"Mapusaurus","rarity":"epic","id":"mapusaurus","subtitle":"Theropod","details":"A giant carcharodontosaurid from Late Cretaceous Argentina, Mapusaurus is known from a bonebed of several individuals of different ages found buried together.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c3/Mapusaurus_reconstruction.jpg"},{"name":"Cryolophosaurus","rarity":"epic","id":"cryolophosaurus","subtitle":"Theropod","details":"A crested predator from Early Jurassic Antarctica, Cryolophosaurus wore a swept-back head crest and is one of the continent's best-known dinosaurs.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/Cryolophosaurus_TD.png/1280px-Cryolophosaurus_TD.png"},{"name":"Coelophysis","rarity":"epic","id":"coelophysis","subtitle":"Theropod","details":"A slender early theropod from Late Triassic southwestern North America, Coelophysis is known from hundreds of skeletons preserved together at Ghost Ranch, New Mexico.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/Coelophysis_TD.png/1280px-Coelophysis_TD.png"},{"name":"Yutyrannus","rarity":"epic","id":"yutyrannus","subtitle":"Theropod","details":"A large early tyrannosaur from Early Cretaceous China, Yutyrannus was preserved with a coat of filamentous feathers, the largest feathered dinosaur known.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Yutyrannus_TD.png/1280px-Yutyrannus_TD.png"},{"name":"Gallimimus","rarity":"rare","id":"gallimimus","subtitle":"Theropod","details":"A large, toothless ostrich mimic from Late Cretaceous Mongolia, Gallimimus was built for speed, with long legs, a long tail and a beak for cropping plants and small prey.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Gallimimus_Restoration.png/1280px-Gallimimus_Restoration.png"},{"name":"Albertosaurus","rarity":"rare","id":"albertosaurus","subtitle":"Theropod","details":"A lighter tyrannosaurid from Late Cretaceous Alberta, Albertosaurus is known from a famous bonebed holding more than twenty individuals of many different ages.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Albertosaurus_TD.png/1280px-Albertosaurus_TD.png"},{"name":"Daspletosaurus","rarity":"rare","id":"daspletosaurus","subtitle":"Theropod","details":"A heavy-set tyrannosaurid from Late Cretaceous western North America, Daspletosaurus was a muscular predator that lived just before T. rex appeared on the scene.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bb/Daspletosaurus_torosus_steveoc_flipped.jpg"},{"name":"Gorgosaurus","rarity":"rare","id":"gorgosaurus","subtitle":"Theropod","details":"A graceful tyrannosaurid from Late Cretaceous Alberta, Gorgosaurus is known from many well-preserved skeletons, including juveniles that show how it grew.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ab/Gorgosaurus_libratus.png"},{"name":"Torvosaurus","rarity":"rare","id":"torvosaurus","subtitle":"Theropod","details":"A big megalosaurid from Late Jurassic North America and Portugal, Torvosaurus carried massive, blade-like teeth and ranked among the largest predators of its age.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Torvosaurus_TD.png/1280px-Torvosaurus_TD.png"},{"name":"Tyrannotitan","rarity":"rare","id":"tyrannotitan","subtitle":"Theropod","details":"An early, giant member of the carcharodontosaurid family from Early Cretaceous Argentina, Tyrannotitan reached about 12 metres and hunted young sauropods.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Tyrannotitan_chubutensis.png/1280px-Tyrannotitan_chubutensis.png"},{"name":"Neovenator","rarity":"rare","id":"neovenator","subtitle":"Theropod","details":"A slender allosauroid predator from Early Cretaceous rocks on the Isle of Wight, Neovenator was a lightly built hunter from England's famous Wealden deposits.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Neovenator.png/1280px-Neovenator.png"},{"name":"Irritator","rarity":"rare","id":"irritator","subtitle":"Theropod","details":"A crested spinosaur from Early Cretaceous Brazil, Irritator had an elongated, fish-catching snout; its name recalls the frustration of restoring its damaged skull.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Irritator_paleoart_by_Sauroarchive.png/1280px-Irritator_paleoart_by_Sauroarchive.png"},{"name":"Compsognathus","rarity":"rare","id":"compsognathus","subtitle":"Theropod","details":"A tiny theropod from Late Jurassic Germany and France, Compsognathus was about the size of a chicken and is one of the smallest non-avian dinosaurs known.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Compsognathus_TD.png/1280px-Compsognathus_TD.png"},{"name":"Microraptor","rarity":"rare","id":"microraptor","subtitle":"Theropod","details":"A tiny four-winged feathered raptor from Early Cretaceous China, Microraptor bore long flight feathers on both arms and legs and likely glided between trees.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Microraptor_Restoration.png/1280px-Microraptor_Restoration.png"},{"name":"Archaeopteryx","rarity":"rare","id":"archaeopteryx","subtitle":"Theropod","details":"A feathered theropod from Late Jurassic Germany at the very origin of birds, Archaeopteryx combined true flight feathers with teeth, clawed fingers and a bony tail.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Archaeopteryx_TD.png/1280px-Archaeopteryx_TD.png"},{"name":"Oviraptor","rarity":"rare","id":"oviraptor","subtitle":"Theropod","details":"A crested theropod from Late Cretaceous Mongolia, Oviraptor was first thought to steal eggs, but fossils show it was brooding its own nest when it died.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Oviraptor_TD.png/1280px-Oviraptor_TD.png"},{"name":"Gigantoraptor","rarity":"rare","id":"gigantoraptor","subtitle":"Theropod","details":"A giant, toothless oviraptorosaur from Late Cretaceous China, Gigantoraptor stood over 3 metres tall at the hip, far bigger than any of its beaked relatives.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Gigantoraptor_TD.png/1280px-Gigantoraptor_TD.png"},{"name":"Concavenator","rarity":"rare","id":"concavenator","subtitle":"Theropod","details":"A carcharodontosaurid from Early Cretaceous Spain, Concavenator had a pointed hump on its back and quill knobs on its arms, hinting at feather-like structures.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Concavenator_TD.png/1280px-Concavenator_TD.png"},{"name":"Dryptosaurus","rarity":"rare","id":"dryptosaurus","subtitle":"Theropod","details":"An eastern North American tyrannosauroid from Late Cretaceous New Jersey, Dryptosaurus retained large, grasping hand claws unlike the tiny arms of later tyrannosaurs.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Dryptosaurus_TD.png/1280px-Dryptosaurus_TD.png"},{"name":"Monolophosaurus","rarity":"rare","id":"monolophosaurus","subtitle":"Theropod","details":"A mid-sized predator from Middle Jurassic China, Monolophosaurus carried a single thin crest running along the top of its snout, likely used for display.","image":"https://images.dinosaurpictures.org/Monolophosaurus-Peter-Minister_94d5.jpg"},{"name":"Ornithomimus","rarity":"uncommon","id":"ornithomimus","subtitle":"Theropod","details":"A toothless ostrich mimic from Late Cretaceous North America, Ornithomimus gave the ostrich-mimic group its name and was built as a fast, long-legged runner.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Ornithomimus_TD.png/1280px-Ornithomimus_TD.png"},{"name":"Struthiomimus","rarity":"uncommon","id":"struthiomimus","subtitle":"Theropod","details":"An ostrich-like runner from Late Cretaceous Alberta, Struthiomimus had long arms, a toothless beak and large eyes, and may have eaten both plants and small animals.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Struthiomimus.png/1280px-Struthiomimus.png"},{"name":"Sinosauropteryx","rarity":"uncommon","id":"sinosauropteryx","subtitle":"Theropod","details":"From Early Cretaceous China, Sinosauropteryx was the first non-avian dinosaur found with feathers, its ringed tail preserved with a banded pattern of colour.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d0/Sinosauropteryx_mmartyniuk_solosml.png"},{"name":"Dromaeosaurus","rarity":"uncommon","id":"dromaeosaurus","subtitle":"Theropod","details":"A sturdy-skulled raptor from Late Cretaceous Alberta, Dromaeosaurus gave the whole dromaeosaur family its name and had a stronger bite than most of its relatives.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Dromaeosaurus_TD.png/1280px-Dromaeosaurus_TD.png"},{"name":"Abelisaurus","rarity":"uncommon","id":"abelisaurus","subtitle":"Theropod","details":"An abelisaur from Late Cretaceous Argentina, Abelisaurus is known mainly from a single, tall skull with rough, rugose bone above its eyes and a deep snout.","image":"https://images.dinosaurpictures.org/Abelisaurus/Abelisaurus_e80880eb.jpg"},{"name":"Aucasaurus","rarity":"uncommon","id":"aucasaurus","subtitle":"Theropod","details":"An abelisaur from Late Cretaceous Argentina found near a sauropod nesting ground, Aucasaurus had even tinier arms than its famous relative Carnotaurus.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ad/Aucasaurus_garridoi_by_Paleocolour.jpg"},{"name":"Rajasaurus","rarity":"uncommon","id":"rajasaurus","subtitle":"Theropod","details":"A horned abelisaur from Late Cretaceous India, Rajasaurus hunted in the Lameta Formation and carried a single low horn on the middle of its forehead.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Rajasaurus_TD.png/1280px-Rajasaurus_TD.png"},{"name":"Skorpiovenator","rarity":"uncommon","id":"skorpiovenator","subtitle":"Theropod","details":"A short, deep-skulled abelisaur from Late Cretaceous Argentina, Skorpiovenator means 'scorpion hunter', named for the scorpions found at its excavation site.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fb/Skorpiovenator_bustingorryi_by_D-Juan.jpg"},{"name":"Ekrixinatosaurus","rarity":"uncommon","id":"ekrixinatosaurus","subtitle":"Theropod","details":"A heavily built abelisaur from mid-Cretaceous Argentina, Ekrixinatosaurus was among the largest of its family, with a short, massive skull and powerful legs.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c9/Ekrixinatosaurus_novasi_by_Henrique_Paes.png"},{"name":"Lythronax","rarity":"uncommon","id":"lythronax","subtitle":"Theropod","details":"An early tyrannosaurid from Late Cretaceous Utah, Lythronax had a wide skull and forward-facing eyes, giving it binocular vision like its later relative T. rex.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Lythronax_TD.png/1280px-Lythronax_TD.png"},{"name":"Afrovenator","rarity":"uncommon","id":"afrovenator","subtitle":"Theropod","details":"A slender megalosaurid from Middle Jurassic Niger, Afrovenator was unearthed in the Sahara and remains one of Africa's best-known Jurassic predators.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Afrovenator_reconstruction.png/1280px-Afrovenator_reconstruction.png"},{"name":"Austroraptor","rarity":"uncommon","id":"austroraptor","subtitle":"Theropod","details":"A large southern raptor from Late Cretaceous Argentina, Austroraptor reached about 5 metres long yet had unusually short arms for a dromaeosaur of its size.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Austroraptor_TD.png/1280px-Austroraptor_TD.png"},{"name":"Sinornithosaurus","rarity":"uncommon","id":"sinornithosaurus","subtitle":"Theropod","details":"A feathered dromaeosaur from Early Cretaceous China, Sinornithosaurus was preserved with long filament feathers along its body, arms and tail, like a downy raptor.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Sinornithosaurus_%28flipped%29.jpg/1280px-Sinornithosaurus_%28flipped%29.jpg"},{"name":"Saurornitholestes","rarity":"uncommon","id":"saurornitholestes","subtitle":"Theropod","details":"A small, nimble raptor from Late Cretaceous North America, Saurornitholestes is known from many fragmentary finds and from tooth marks it left on larger dinosaurs.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Saurornitholestes_langstoni.png/1280px-Saurornitholestes_langstoni.png"},{"name":"Bambiraptor","rarity":"uncommon","id":"bambiraptor","subtitle":"Theropod","details":"A small juvenile raptor from Late Cretaceous Montana, Bambiraptor had a proportionally large brain and long legs, and was named after the young deer Bambi.","image":"https://upload.wikimedia.org/wikipedia/commons/d/df/Bambiraptor_NT.jpg"},{"name":"Nanuqsaurus","rarity":"uncommon","id":"nanuqsaurus","subtitle":"Theropod","details":"A polar tyrannosaur from Late Cretaceous Alaska, Nanuqsaurus means 'polar bear lizard' and was a smaller relative of T. rex adapted to Arctic darkness.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Nanuqsaurus_TD.png/1280px-Nanuqsaurus_TD.png"},{"name":"Ichthyovenator","rarity":"uncommon","id":"ichthyovenator","subtitle":"Theropod","details":"A spinosaur from Early Cretaceous Laos, Ichthyovenator had a distinctive notched sail over its hips, split by a dip unlike the smooth sails of its relatives.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Ichthyovenator_laosensis_life_reconstruction_by_PaleoGeek.png/1280px-Ichthyovenator_laosensis_life_reconstruction_by_PaleoGeek.png"},{"name":"Citipati","rarity":"uncommon","id":"citipati","subtitle":"Theropod","details":"A crested oviraptorid from Late Cretaceous Mongolia, Citipati is famously preserved brooding on its nest, arms spread over its eggs in a bird-like pose.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Citipati_TD.png/1280px-Citipati_TD.png"},{"name":"Erlikosaurus","rarity":"uncommon","id":"erlikosaurus","subtitle":"Theropod","details":"A therizinosaur from Late Cretaceous Mongolia, Erlikosaurus is known from a well-preserved beaked skull, one of the most complete known for its strange group.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/Erlikosaurus_Restoration.png/1280px-Erlikosaurus_Restoration.png"},{"name":"Segnosaurus","rarity":"uncommon","id":"segnosaurus","subtitle":"Theropod","details":"A bulky therizinosaur from Late Cretaceous Mongolia, Segnosaurus combined big hand claws with a toothless beak tip and wide hips built for a large plant-filled gut.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Segnosaurus_Restoration.jpg/1280px-Segnosaurus_Restoration.jpg"},{"name":"Nothronychus","rarity":"uncommon","id":"nothronychus","subtitle":"Theropod","details":"A pot-bellied leaf-eater from Late Cretaceous southwestern North America, Nothronychus was the first therizinosaur ever discovered outside Asia, found in New Mexico.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Nothronychus_mckinleyi_Restoration.png/1280px-Nothronychus_mckinleyi_Restoration.png"},{"name":"Falcarius","rarity":"uncommon","id":"falcarius","subtitle":"Theropod","details":"An early therizinosaur from Early Cretaceous Utah, Falcarius bridges the shift from meat to plants, mixing a predator's build with small, leaf-shaped teeth.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Falcarius_Restoration.png/1280px-Falcarius_Restoration.png"},{"name":"Dilong","rarity":"uncommon","id":"dilong","subtitle":"Theropod","details":"A small early tyrannosauroid from Early Cretaceous China, Dilong was covered in simple filament feathers, early evidence that tyrannosaurs began feathered.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2b/Dilong_scratching_02.png"},{"name":"Guanlong","rarity":"uncommon","id":"guanlong","subtitle":"Theropod","details":"A crested early tyrannosaur relative from Late Jurassic China, Guanlong carried a tall, fragile head crest, one of the most elaborate known on any theropod.","image":"https://upload.wikimedia.org/wikipedia/commons/8/89/Guanlong_TD.png"},{"name":"Juravenator","rarity":"uncommon","id":"juravenator","subtitle":"Theropod","details":"A small theropod from Late Jurassic Germany, Juravenator is known from an exquisitely preserved juvenile with skin impressions showing scales near its tail.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Juravenator_by_Tom_Parker.png/1280px-Juravenator_by_Tom_Parker.png"},{"name":"Eustreptospondylus","rarity":"uncommon","id":"eustreptospondylus","subtitle":"Theropod","details":"A megalosaurid from Middle Jurassic England, Eustreptospondylus was washed into the sea from a Jurassic island coastline and found as a complete skeleton.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5f/Eustrept1DB1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Fukuiraptor","rarity":"uncommon","id":"fukuiraptor","subtitle":"Theropod","details":"A megaraptor from Early Cretaceous Japan, Fukuiraptor bore oversized hand claws and was first taken for a giant raptor because of its huge thumb claw.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2f/Fukuiraptor_BW.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Megaraptor","rarity":"uncommon","id":"megaraptor","subtitle":"Theropod","details":"From Late Cretaceous Argentina, Megaraptor's huge curved claw was originally mistaken for a raptor's foot claw before it was recognised as a hand claw.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/Megaraptor_TD.png/1280px-Megaraptor_TD.png"},{"name":"Deltadromeus","rarity":"uncommon","id":"deltadromeus","subtitle":"Theropod","details":"A long-legged, slender-built predator from mid-Cretaceous Morocco, Deltadromeus prowled the Kem Kem beds alongside giants such as Spinosaurus and Carcharodontosaurus.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Deltadromeus31DB.jpg/1280px-Deltadromeus31DB.jpg"},{"name":"Yangchuanosaurus","rarity":"uncommon","id":"yangchuanosaurus","subtitle":"Theropod","details":"A large metriacanthosaurid from Late Jurassic China, Yangchuanosaurus was the top predator of its formation, reaching about 8 metres and hunting stegosaurs.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Yangchuanosaurus_TD.png/1280px-Yangchuanosaurus_TD.png"},{"name":"Sinraptor","rarity":"uncommon","id":"sinraptor","subtitle":"Theropod","details":"A metriacanthosaurid from Late Jurassic China, Sinraptor had a low, roughened crest along its snout and hunted alongside the stegosaur herds of its formation.","image":"https://upload.wikimedia.org/wikipedia/commons/9/96/Sinraptor_NT_%28no_bg%29.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Marshosaurus","rarity":"common","id":"marshosaurus","subtitle":"Theropod","details":"A mid-sized predator from Late Jurassic Utah, Marshosaurus hunted in the Morrison Formation and is known from partial skeletons of several individuals.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Marshosaurus_TD.png/1280px-Marshosaurus_TD.png"},{"name":"Stokesosaurus","rarity":"common","id":"stokesosaurus","subtitle":"Theropod","details":"A small, early tyrannosauroid from Late Jurassic Utah, Stokesosaurus was a lightly built Morrison Formation predator that lived long before Tyrannosaurus.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Stokesosaurus_by_Tom_Parker.png/1280px-Stokesosaurus_by_Tom_Parker.png"},{"name":"Eotyrannus","rarity":"common","id":"eotyrannus","subtitle":"Theropod","details":"A slender early tyrannosauroid from Early Cretaceous England, Eotyrannus lived on the Isle of Wight and kept long, three-fingered hands for grasping prey.","image":"https://upload.wikimedia.org/wikipedia/commons/8/84/Eotyrannus_1_NT.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Proceratosaurus","rarity":"common","id":"proceratosaurus","subtitle":"Theropod","details":"A small early tyrannosauroid from Middle Jurassic England, Proceratosaurus bore a partial crest on its head and hunted small prey in coastal woodlands.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9a/Proceratosaurus_restoration.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Chilantaisaurus","rarity":"common","id":"chilantaisaurus","subtitle":"Theropod","details":"A large allosauroid from Late Cretaceous China, Chilantaisaurus is known partly from huge, raptor-like claw bones on its hands, used to seize its prey.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Chilantaisaurus.jpg/1280px-Chilantaisaurus.jpg"},{"name":"Alectrosaurus","rarity":"common","id":"alectrosaurus","subtitle":"Theropod","details":"A long-legged tyrannosauroid from Late Cretaceous Mongolia, Alectrosaurus was a fast-running predator known only from partial hind limbs and other remains.","image":"https://upload.wikimedia.org/wikipedia/commons/2/25/Alectrosaurus_flipped.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Alioramus","rarity":"common","id":"alioramus","subtitle":"Theropod","details":"A slim tyrannosaurid from Late Cretaceous Mongolia, Alioramus had a long, narrow snout marked by a row of small bony bumps along its top surface.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/Alioramus_Life_Restoration.jpg/1280px-Alioramus_Life_Restoration.jpg"},{"name":"Appalachiosaurus","rarity":"common","id":"appalachiosaurus","subtitle":"Theropod","details":"A tyrannosauroid from Late Cretaceous Alabama, Appalachiosaurus lived on the island continent of Appalachia, separated by a shallow inland sea.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Appalachiosaurus_TD.png/1280px-Appalachiosaurus_TD.png"},{"name":"Bistahieversor","rarity":"common","id":"bistahieversor","subtitle":"Theropod","details":"A deep-skulled tyrannosaurid from Late Cretaceous New Mexico, Bistahieversor had extra openings in its skull and a powerful, bone-crushing bite.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Bistahieversor_sealeyi_life_restoration.jpg/1280px-Bistahieversor_sealeyi_life_restoration.jpg"},{"name":"Rugops","rarity":"common","id":"rugops","subtitle":"Theropod","details":"An abelisaur from Late Cretaceous Niger, Rugops had a lightly built, ornamented skull with a rough, wrinkled texture across the top of its snout.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Rugops_reconstruction.jpg/1280px-Rugops_reconstruction.jpg"},{"name":"Atrociraptor","rarity":"common","id":"atrociraptor","subtitle":"Theropod","details":"A short-faced raptor from Late Cretaceous Alberta, Atrociraptor had an unusually deep snout and curved hand and foot claws for tackling small prey.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0b/Atrociraptor.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Gobivenator","rarity":"common","id":"gobivenator","subtitle":"Theropod","details":"A small troodontid from Late Cretaceous Mongolia, Gobivenator is known from a nearly complete skeleton, with large eyes and a lightly built skull.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1c/Gobivenator_Restoration.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Qianzhousaurus","rarity":"common","id":"qianzhousaurus","subtitle":"Theropod","details":"A long-snouted tyrannosaurid from Late Cretaceous China, Qianzhousaurus was nicknamed 'Pinocchio rex' for its unusually elongated, narrow skull.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Qianzhousaurus_sinensis_by_PaleoGeek.png/1280px-Qianzhousaurus_sinensis_by_PaleoGeek.png"},{"name":"Teratophoneus","rarity":"common","id":"teratophoneus","subtitle":"Theropod","details":"A tyrannosaurid from Late Cretaceous Utah, Teratophoneus prowled the fossil-rich Kaiparowits Formation alongside horned dinosaurs and duckbills.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cf/Teratophoneus2_NT.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Thanatotheristes","rarity":"common","id":"thanatotheristes","subtitle":"Theropod","details":"A rugged-snouted tyrannosaurid from Late Cretaceous Alberta, Thanatotheristes means 'reaper of death' and had ridges and scars across its snout.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/Thanatotheristes_degrootorum.jpg/1280px-Thanatotheristes_degrootorum.jpg"},{"name":"Zhuchengtyrannus","rarity":"common","id":"zhuchengtyrannus","subtitle":"Theropod","details":"A giant tyrannosaurid from Late Cretaceous China, Zhuchengtyrannus is known mainly from massive jaw bones rivalling those of Tyrannosaurus itself.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/ZhuchengtyrannusJF.png/1280px-ZhuchengtyrannusJF.png"},{"name":"Masiakasaurus","rarity":"common","id":"masiakasaurus","subtitle":"Theropod","details":"A small noasaur from Late Cretaceous Madagascar, Masiakasaurus had front teeth that jutted forward at an angle, unlike those of any other theropod.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Masiakasaurus_LMR.png/1280px-Masiakasaurus_LMR.png"},{"name":"Limusaurus","rarity":"common","id":"limusaurus","subtitle":"Theropod","details":"A toothless, plant-eating ceratosaur from Late Jurassic China, Limusaurus lost its teeth as it grew, shifting from an omnivorous juvenile to herbivore.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Limusaurus_runner.jpg/1280px-Limusaurus_runner.jpg"},{"name":"Noasaurus","rarity":"common","id":"noasaurus","subtitle":"Theropod","details":"A small ceratosaur from Late Cretaceous Argentina, Noasaurus was once wrongly thought to carry a raptor-like foot claw, later shown to be a hand claw.","image":"https://images.dinosaurpictures.org/Noasaurus/Noasaurus_346170b0.jpg"},{"name":"Elaphrosaurus","rarity":"common","id":"elaphrosaurus","subtitle":"Theropod","details":"A long-necked, slender ceratosaur from Late Jurassic Tanzania, Elaphrosaurus came from the Tendaguru beds and had a lightly built, long-legged body.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Elaphrosaurus.jpg/1280px-Elaphrosaurus.jpg"},{"name":"Scipionyx","rarity":"common","id":"scipionyx","subtitle":"Theropod","details":"A juvenile theropod from Early Cretaceous Italy, Scipionyx is so well preserved that its fossil shows traces of internal organs and soft tissues.","image":"https://carnegiemnh.org/wp-content/uploads/2020/11/7935011d47503c628bcfb1ca292d87a1d0608259.jpg"},{"name":"Caudipteryx","rarity":"common","id":"caudipteryx","subtitle":"Theropod","details":"A small feathered oviraptorosaur from Early Cretaceous China, Caudipteryx had a fan of long tail feathers and short, feathered arms like small wings.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Caudipteryx_TD.png/1280px-Caudipteryx_TD.png"},{"name":"Incisivosaurus","rarity":"common","id":"incisivosaurus","subtitle":"Theropod","details":"A small oviraptorosaur from Early Cretaceous China, Incisivosaurus had prominent, buck-toothed front teeth suited to a largely plant-based diet.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/Incisivosaurus_TD.png/1280px-Incisivosaurus_TD.png"},{"name":"Avimimus","rarity":"common","id":"avimimus","subtitle":"Theropod","details":"A bird-like, toothless oviraptorosaur from Late Cretaceous Mongolia, Avimimus had a short beak, long legs, and fused hand bones much like a bird.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0f/Avimimus_mmartyniuk_wiki.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Chirostenotes","rarity":"common","id":"chirostenotes","subtitle":"Theropod","details":"A long-legged, beaked oviraptorosaur from Late Cretaceous Alberta, Chirostenotes is known largely from its elegant, slender hands and feet bones.","image":"https://images.dinosaurpictures.org/Chirostenotes/Chirostenotes_d48c291e.jpg"},{"name":"Nemegtomaia","rarity":"common","id":"nemegtomaia","subtitle":"Theropod","details":"A crested oviraptorid from Late Cretaceous Mongolia, Nemegtomaia is known from a specimen preserved sitting over a nest of its own ring-shaped eggs.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Nemegtomaia_Restoration.png/1280px-Nemegtomaia_Restoration.png"},{"name":"Khaan","rarity":"common","id":"khaan","subtitle":"Theropod","details":"A small oviraptorid from Late Cretaceous Mongolia, Khaan is famous for a pair of individuals found preserved side by side in the Gobi Desert sands.","image":"https://images.dinosaurpictures.org/Khaan/Khaan_424abc94.jpg"},{"name":"Haplocheirus","rarity":"common","id":"haplocheirus","subtitle":"Theropod","details":"An early alvarezsaur from Late Jurassic China, Haplocheirus still kept a grasping, three-fingered hand, unlike its later single-clawed relatives.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ef/Haplocheirus_NT.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Shuvuuia","rarity":"common","id":"shuvuuia","subtitle":"Theropod","details":"A desert alvarezsaur from Late Cretaceous Mongolia, Shuvuuia had one huge thumb claw, a bird-like skull, and stiff legs built for fast running.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Shuvuuia_TD.png/1280px-Shuvuuia_TD.png"},{"name":"Mononykus","rarity":"common","id":"mononykus","subtitle":"Theropod","details":"A single-clawed alvarezsaur from Late Cretaceous Mongolia, Mononykus was built like a digging specialist, using its stout arms to break into nests.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Mononykus_TD.png/1280px-Mononykus_TD.png"},{"name":"Alvarezsaurus","rarity":"common","id":"alvarezsaurus","subtitle":"Theropod","details":"A small, long-legged alvarezsaur from Late Cretaceous Argentina, Alvarezsaurus gave its unusual family its name and ran swiftly across dry plains.","image":"https://upload.wikimedia.org/wikipedia/commons/2/21/Alvarezsaurus_calvoi.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Pelecanimimus","rarity":"common","id":"pelecanimimus","subtitle":"Theropod","details":"An early ostrich mimic from Early Cretaceous Spain, Pelecanimimus kept many small teeth, more than any other ornithomimosaur, plus a small head crest.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Pelecanimimus_TD.png/1280px-Pelecanimimus_TD.png"},{"name":"Harpymimus","rarity":"common","id":"harpymimus","subtitle":"Theropod","details":"An early ornithomimosaur from Early Cretaceous Mongolia, Harpymimus still kept a few small teeth in its lower jaw, unlike later toothless relatives.","image":"https://upload.wikimedia.org/wikipedia/commons/7/70/Harpymimus_steveoc.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Garudimimus","rarity":"common","id":"garudimimus","subtitle":"Theropod","details":"An ostrich mimic from Late Cretaceous Mongolia, Garudimimus had a small horn-like crest on its skull, long running legs, and a toothless beaked jaw.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Garudimimus_Restoration.png/1280px-Garudimimus_Restoration.png"},{"name":"Anserimimus","rarity":"common","id":"anserimimus","subtitle":"Theropod","details":"An ostrich mimic from Late Cretaceous Mongolia, Anserimimus had unusually strong arms and large claws, differing from its more lightly built kin.","image":"https://images.dinosaurpictures.org/Anserimimus/Anserimimus_d92cc208.jpg"},{"name":"Archaeornithomimus","rarity":"common","id":"archaeornithomimus","subtitle":"Theropod","details":"An ornithomimosaur from Late Cretaceous China, Archaeornithomimus is known from jumbled masses of bones from many individuals found together.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Archaeornithomimus.png/1280px-Archaeornithomimus.png"},{"name":"Buitreraptor","rarity":"common","id":"buitreraptor","subtitle":"Theropod","details":"A long-snouted southern raptor from Late Cretaceous Argentina, Buitreraptor had many small, unserrated teeth for snapping up small animals.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Buitreraptor_TD.png/1280px-Buitreraptor_TD.png"},{"name":"Pyroraptor","rarity":"common","id":"pyroraptor","subtitle":"Theropod","details":"A European raptor from Late Cretaceous France, Pyroraptor was nicknamed 'fire thief' because its fossil site burned in a forest fire after discovery.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Pyroraptor_olympius.png/1280px-Pyroraptor_olympius.png"},{"name":"Achillobator","rarity":"common","id":"achillobator","subtitle":"Theropod","details":"A large, robust raptor from Late Cretaceous Mongolia, Achillobator had a stiffened tail, powerful hips, and a large sickle claw on each foot.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Achillobator_TD.png/1280px-Achillobator_TD.png"},{"name":"Zhenyuanlong","rarity":"common","id":"zhenyuanlong","subtitle":"Theropod","details":"A feathered raptor from Early Cretaceous China, Zhenyuanlong was preserved with large, wing-like feathered arms, though it was too heavy to fly.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f7/Zhenyuanlong_life_restoration_%28white_background%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Brachiosaurus","rarity":"chase","id":"brachiosaurus","subtitle":"Sauropod","details":"A giant sauropod from Late Jurassic North America, Brachiosaurus had front legs longer than its hind legs, giving it a giraffe-like, head-high stance.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Brachiosaurus_TD.png/1280px-Brachiosaurus_TD.png"},{"name":"Diplodocus","rarity":"chase","id":"diplodocus","subtitle":"Sauropod","details":"A long-necked sauropod from Late Jurassic North America, Diplodocus had pencil-like teeth at the front of its jaws and an extremely long, whip-like tail.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Diplodocus_TD.png/1280px-Diplodocus_TD.png"},{"name":"Apatosaurus","rarity":"legendary","id":"apatosaurus","subtitle":"Sauropod","details":"A stocky-necked giant from Late Jurassic North America, Apatosaurus was one of the first sauropods ever mounted for display in a museum exhibition.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/Apatosaurus_TD.png/1280px-Apatosaurus_TD.png"},{"name":"Brontosaurus","rarity":"legendary","id":"brontosaurus","subtitle":"Sauropod","details":"A long-necked Morrison Formation grazer from Late Jurassic North America, Brontosaurus had its famous name restored as a valid genus in 2015.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Brontosaurus_TD.png/1280px-Brontosaurus_TD.png"},{"name":"Argentinosaurus","rarity":"legendary","id":"argentinosaurus","subtitle":"Sauropod","details":"A giant titanosaur from Late Cretaceous Argentina, Argentinosaurus is known from enormous vertebrae and limb bones, among the largest for a sauropod.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Argentinosaurus_TD.png/1280px-Argentinosaurus_TD.png"},{"name":"Camarasaurus","rarity":"legendary","id":"camarasaurus","subtitle":"Sauropod","details":"The most common sauropod of the Late Jurassic Morrison Formation, Camarasaurus had a boxy skull and spoon-shaped teeth for cropping coarse plants.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Camarasaurus_TD.png/1280px-Camarasaurus_TD.png"},{"name":"Giraffatitan","rarity":"epic","id":"giraffatitan","subtitle":"Sauropod","details":"A tall brachiosaur relative from Late Jurassic Tanzania, Giraffatitan carried a high, rounded crest on its skull and browsed high in the treetops.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Giraffatitan_TD.png/1280px-Giraffatitan_TD.png"},{"name":"Mamenchisaurus","rarity":"epic","id":"mamenchisaurus","subtitle":"Sauropod","details":"A sauropod from Late Jurassic China, Mamenchisaurus had an extraordinary neck that made up close to half its total length in some known species.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Mamenchisaurus_TD.png/1280px-Mamenchisaurus_TD.png"},{"name":"Patagotitan","rarity":"epic","id":"patagotitan","subtitle":"Sauropod","details":"Among the largest titanosaurs known, Patagotitan lived in Early Cretaceous Argentina and is known from several skeletons rather than a single find.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Patagotitan_TD.png/1280px-Patagotitan_TD.png"},{"name":"Supersaurus","rarity":"epic","id":"supersaurus","subtitle":"Sauropod","details":"A very long diplodocid from Late Jurassic North America, Supersaurus was first recognised from a single huge shoulder blade found in Colorado.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/Supersaurus_TD.png/1280px-Supersaurus_TD.png"},{"name":"Barosaurus","rarity":"epic","id":"barosaurus","subtitle":"Sauropod","details":"A diplodocid from Late Jurassic North America, Barosaurus had an especially long neck, even for its long-necked family, with many neck vertebrae.","image":"https://images.dinosaurpictures.org/Barosaurus/Barosaurus_da60131e.jpg"},{"name":"Amargasaurus","rarity":"epic","id":"amargasaurus","subtitle":"Sauropod","details":"A sauropod from Early Cretaceous Argentina, Amargasaurus carried paired rows of tall, slender spines running down its neck and along its back.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Amargasaurus_Reconstruction_Fred_Wierum.png/1280px-Amargasaurus_Reconstruction_Fred_Wierum.png"},{"name":"Alamosaurus","rarity":"rare","id":"alamosaurus","subtitle":"Sauropod","details":"A titanosaur from Late Cretaceous North America, Alamosaurus lived alongside Tyrannosaurus at the very end of the dinosaur era in the southwest.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Alamosaurus_TD.png/1280px-Alamosaurus_TD.png"},{"name":"Saltasaurus","rarity":"rare","id":"saltasaurus","subtitle":"Sauropod","details":"A relatively small titanosaur from Late Cretaceous Argentina, Saltasaurus had bony studs of armour embedded in its skin for added protection.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Saltasaurus_TD.png/1280px-Saltasaurus_TD.png"},{"name":"Futalognkosaurus","rarity":"rare","id":"futalognkosaurus","subtitle":"Sauropod","details":"A giant titanosaur from Late Cretaceous Argentina, Futalognkosaurus is known from an unusually complete neck, torso, and hips for such a huge animal.","image":"https://upload.wikimedia.org/wikipedia/commons/2/28/Futalognkosaurus_BW.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"},{"name":"Dreadnoughtus","rarity":"rare","id":"dreadnoughtus","subtitle":"Sauropod","details":"A huge titanosaur from Late Cretaceous Argentina, Dreadnoughtus is known from an exceptionally complete skeleton for an animal of its great size.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6c/Dreadnoughtus_NT_small.jpg"},{"name":"Nigersaurus","rarity":"rare","id":"nigersaurus","subtitle":"Sauropod","details":"A broad, square-muzzled grazer from Middle Cretaceous Niger, Nigersaurus had more than 500 teeth and fed low, like a vacuum cleaner at ground level.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Nigersaurus_TD.png/1280px-Nigersaurus_TD.png"},{"name":"Cetiosaurus","rarity":"rare","id":"cetiosaurus","subtitle":"Sauropod","details":"One of the first sauropods ever named, Cetiosaurus came from Middle Jurassic England and was recognised as a giant before dinosaurs had a name.","image":"https://upload.wikimedia.org/wikipedia/commons/0/02/Cetiosaurus_BW.jpg"},{"name":"Titanosaurus","rarity":"rare","id":"titanosaurus","subtitle":"Sauropod","details":"The namesake of the titanosaurs, Titanosaurus lived in Late Cretaceous India, though it is known only from limited remains of its limbs and hips.","image":"https://images.dinosaurpictures.org/titanosaurus-colberti-2_4c21.jpg"},{"name":"Shunosaurus","rarity":"rare","id":"shunosaurus","subtitle":"Sauropod","details":"A relatively short-necked sauropod from Middle Jurassic China, Shunosaurus was tipped with a small bony club at the end of its muscular tail.","image":"https://upload.wikimedia.org/wikipedia/commons/1/16/Shunosaurus_life_restoration.jpg"},{"name":"Europasaurus","rarity":"rare","id":"europasaurus","subtitle":"Sauropod","details":"An island dwarf sauropod from Late Jurassic Germany, Europasaurus grew to only about six metres long in its restricted island habitat setting.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Europasaurus_TD.png/1280px-Europasaurus_TD.png"},{"name":"Dicraeosaurus","rarity":"rare","id":"dicraeosaurus","subtitle":"Sauropod","details":"A short-necked diplodocid relative from Late Jurassic Tanzania, Dicraeosaurus had paired spines along its back and a comparatively small body.","image":"https://upload.wikimedia.org/wikipedia/commons/9/97/Dicraeosaurus_hansemanni22.jpg"},{"name":"Sauroposeidon","rarity":"uncommon","id":"sauroposeidon","subtitle":"Sauropod","details":"Known from huge neck vertebrae in Oklahoma and Texas, Sauroposeidon was among the tallest sauropods yet found in Early Cretaceous North America.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Sauroposeidon_TD.png/1280px-Sauroposeidon_TD.png"},{"name":"Turiasaurus","rarity":"uncommon","id":"turiasaurus","subtitle":"Sauropod","details":"A giant sauropod from Late Jurassic Spain, Turiasaurus is one of the largest dinosaurs known from Europe, with massive limb bones and teeth.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Turiasaurus_tarde.png/500px-Turiasaurus_tarde.png"},{"name":"Rapetosaurus","rarity":"uncommon","id":"rapetosaurus","subtitle":"Sauropod","details":"A titanosaur from Late Cretaceous Madagascar, Rapetosaurus is rare among its kind for being known from a complete skull as well as its skeleton.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Rapetosaurus_TD.png/1280px-Rapetosaurus_TD.png"},{"name":"Opisthocoelicaudia","rarity":"uncommon","id":"opisthocoelicaudia","subtitle":"Sauropod","details":"A titanosaur from Late Cretaceous Mongolia, Opisthocoelicaudia is known almost entirely from its body — its skull has never been found at all.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fe/Opisthocoelicaudia.jpg"},{"name":"Vulcanodon","rarity":"uncommon","id":"vulcanodon","subtitle":"Sauropod","details":"One of the earliest true sauropods, Vulcanodon lived in Early Jurassic Zimbabwe and already walked on straight, pillar-like legs under its body.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d0/Vulcanodon_NT.jpg"},{"name":"Jobaria","rarity":"uncommon","id":"jobaria","subtitle":"Sauropod","details":"An unusually primitive sauropod from Cretaceous Niger, Jobaria survived long after its close relatives had evolved into more advanced forms.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f6/Jobaria_tiguidensis_steveoc.jpg"},{"name":"Paralititan","rarity":"uncommon","id":"paralititan","subtitle":"Sauropod","details":"A giant titanosaur from Late Cretaceous Egypt, Paralititan browsed in coastal mangrove swamps, where its bones were preserved in tidal deposits.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Paralititan_stromeri.jpg/1280px-Paralititan_stromeri.jpg"},{"name":"Malawisaurus","rarity":"uncommon","id":"malawisaurus","subtitle":"Sauropod","details":"An African titanosaur from Early Cretaceous Malawi, Malawisaurus is known from rare skull material as well as bones of its neck, body, and limbs.","image":"https://images.dinosaurpictures.org/Malawisaurus2_5f81.jpg"},{"name":"Omeisaurus","rarity":"uncommon","id":"omeisaurus","subtitle":"Sauropod","details":"A Middle Jurassic sauropod from China, Omeisaurus stretched its long neck over fern prairies to browse foliage, and some species carried a small club at the tail tip.","image":"https://images.dinosaurpictures.org/Omeisaurus/Omeisaurus_78817965.jpg"},{"name":"Barapasaurus","rarity":"uncommon","id":"barapasaurus","subtitle":"Sauropod","details":"From Early Jurassic India, Barapasaurus was one of the earliest truly large sauropods, known from the bones of many individuals found together in floodplain deposits.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Barapasaurus_TD.png/1280px-Barapasaurus_TD.png"},{"name":"Isanosaurus","rarity":"uncommon","id":"isanosaurus","subtitle":"Sauropod","details":"A Late Triassic sauropod from Thailand, Isanosaurus stands among the very earliest known members of its group, appearing near the dawn of the giant long-necked dinosaurs.","image":"https://images.dinosaurpictures.org/Isanosaurus/Isanosaurus_c3bfe160.jpg"},{"name":"Euhelopus","rarity":"uncommon","id":"euhelopus","subtitle":"Sauropod","details":"An Early Cretaceous sauropod from China, Euhelopus was unusual in having front legs longer than its hind legs, giving its long neck a gentle upward slope as it browsed.","image":"https://upload.wikimedia.org/wikipedia/commons/9/90/EuhelopusDB2.jpg"},{"name":"Brachytrachelopan","rarity":"uncommon","id":"brachytrachelopan","subtitle":"Sauropod","details":"A Late Jurassic sauropod from Argentina, Brachytrachelopan had the shortest neck relative to its body of any known sauropod, a stubby contrast to its long-necked cousins.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Brachytrachelopan_TD.png/1280px-Brachytrachelopan_TD.png"},{"name":"Rebbachisaurus","rarity":"uncommon","id":"rebbachisaurus","subtitle":"Sauropod","details":"A Middle Cretaceous sauropod from North Africa, Rebbachisaurus carried tall spines along its back that formed a raised, sail-like ridge above its shoulders and hips.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Rebbachisaurus_TD.png/1280px-Rebbachisaurus_TD.png"},{"name":"Diamantinasaurus","rarity":"uncommon","id":"diamantinasaurus","subtitle":"Sauropod","details":"A stocky titanosaur from Middle Cretaceous Australia, Diamantinasaurus is known from Queensland's Winton Formation, a land of rivers, lakes and seasonal floodplains.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Diamantinasaurus.png/1280px-Diamantinasaurus.png"},{"name":"Tapuiasaurus","rarity":"uncommon","id":"tapuiasaurus","subtitle":"Sauropod","details":"An Early Cretaceous titanosaur from Brazil, Tapuiasaurus is prized for its rare complete skull, which revealed a long, low head unlike most other sauropod skull finds.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bc/Tapuiasaurus_NT.jpg"},{"name":"Abydosaurus","rarity":"common","id":"abydosaurus","subtitle":"Sauropod","details":"An Early Cretaceous brachiosaur relative from Utah, Abydosaurus is unusual among sauropods for being known from complete skulls, including those of young animals.","image":"https://images.dinosaurpictures.org/abydosaurus-_1b66.jpg"},{"name":"Aragosaurus","rarity":"common","id":"aragosaurus","subtitle":"Sauropod","details":"An Early Cretaceous sauropod from Spain, Aragosaurus holds a place in history as the first dinosaur genus ever named from Spanish rocks, found in the province of Teruel.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Aragosaurus_tarde.png/500px-Aragosaurus_tarde.png"},{"name":"Rhoetosaurus","rarity":"common","id":"rhoetosaurus","subtitle":"Sauropod","details":"A Middle Jurassic sauropod from Australia, Rhoetosaurus was one of the earliest sauropods known from that continent, represented by a partial skeleton from Queensland.","image":"https://images.dinosaurpictures.org/Rhoetosaurus/Rhoetosaurus_389d571c.jpg"},{"name":"Wintonotitan","rarity":"common","id":"wintonotitan","subtitle":"Sauropod","details":"A Middle Cretaceous sauropod from Queensland, Australia, Wintonotitan was a slender-limbed titanosaur that shared its floodplain home with many other giant herbivores.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e0/Wintonotitan.png/1280px-Wintonotitan.png"},{"name":"Savannasaurus","rarity":"common","id":"savannasaurus","subtitle":"Sauropod","details":"A Middle Cretaceous titanosaur from Australia, Savannasaurus had unusually wide hips and a broad ribcage, giving this Queensland sauropod a barrel-bodied build.","image":"https://images.dinosaurpictures.org/Savannasaurus/image_4303_1e-Savannasaurus-elliottorum_0a11.jpg"},{"name":"Phuwiangosaurus","rarity":"common","id":"phuwiangosaurus","subtitle":"Sauropod","details":"An Early Cretaceous sauropod from Thailand, Phuwiangosaurus is known from both juvenile and adult remains, offering a rare look at how these titanosaurs grew up.","image":"https://images.dinosaurpictures.org/Phuwiangosaurus/Phuwiangosaurus_e7757f5e.jpg"},{"name":"Bellusaurus","rarity":"common","id":"bellusaurus","subtitle":"Sauropod","details":"A Late Jurassic sauropod from China, Bellusaurus is known from a group of young animals found together, a cluster of juveniles preserved in the rocks of Xinjiang.","image":"https://upload.wikimedia.org/wikipedia/commons/2/25/Bellusaurus-v1.jpg"},{"name":"Kotasaurus","rarity":"common","id":"kotasaurus","subtitle":"Sauropod","details":"An Early Jurassic sauropod from India, Kotasaurus mixed primitive features with more advanced ones, capturing an early stage in the evolution of the giant sauropods.","image":"https://images.dinosaurpictures.org/Pcab261_kotasaurus_813f.jpg"},{"name":"Antetonitrus","rarity":"common","id":"antetonitrus","subtitle":"Sauropod","details":"From Late Triassic to Early Jurassic South Africa, Antetonitrus was a transitional form close to the base of the sauropod family tree, foreshadowing later giants.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Antetonitrus_reconstruction.jpg/1280px-Antetonitrus_reconstruction.jpg"},{"name":"Tazoudasaurus","rarity":"common","id":"tazoudasaurus","subtitle":"Sauropod","details":"An Early Jurassic sauropod from Morocco, Tazoudasaurus is known from well-preserved remains that rank it among the best understood of the earliest true sauropods.","image":"https://images.dinosaurpictures.org/Tazoudasaurus_2252.jpg"},{"name":"Haplocanthosaurus","rarity":"common","id":"haplocanthosaurus","subtitle":"Sauropod","details":"A Late Jurassic sauropod of western North America, Haplocanthosaurus was smaller and rarer than its Morrison Formation neighbours, known from only a few skeletons.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Haplocanthosaurus_sp_life_restoration.png/1280px-Haplocanthosaurus_sp_life_restoration.png"},{"name":"Cedarosaurus","rarity":"common","id":"cedarosaurus","subtitle":"Sauropod","details":"An Early Cretaceous brachiosaur relative from Utah, Cedarosaurus was found with polished stomach stones it had swallowed, likely to help grind tough plant food.","image":"https://upload.wikimedia.org/wikipedia/commons/4/40/Cedarosaurus_SW.png"},{"name":"Sonorasaurus","rarity":"common","id":"sonorasaurus","subtitle":"Sauropod","details":"A Middle Cretaceous brachiosaur relative from Arizona, Sonorasaurus is honoured as Arizona's state dinosaur and remains the best-known sauropod found in that state.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Sonorasaurus_thompsoni.jpg/1280px-Sonorasaurus_thompsoni.jpg"},{"name":"Moabosaurus","rarity":"common","id":"moabosaurus","subtitle":"Sauropod","details":"An Early Cretaceous turiasaur sauropod from Utah, Moabosaurus was named after the town of Moab, near the red-rock badlands where its bones were first uncovered.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Moabosaurus_utahensis_restoration.png/1280px-Moabosaurus_utahensis_restoration.png"},{"name":"Venenosaurus","rarity":"common","id":"venenosaurus","subtitle":"Sauropod","details":"An Early Cretaceous brachiosaur relative from Utah, Venenosaurus was a smaller sauropod named for the Poison Strip area where its partial skeleton was discovered.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Ilustracion_de_Venenosaurus.png/1280px-Ilustracion_de_Venenosaurus.png"},{"name":"Erketu","rarity":"common","id":"erketu","subtitle":"Sauropod","details":"A Late Cretaceous sauropod from Mongolia, Erketu had an exceptionally long neck even compared with its own trunk, among the most elongated proportions in its group.","image":"https://images.dinosaurpictures.org/Erketu-Berislav-Krzic_7278.jpg"},{"name":"Nemegtosaurus","rarity":"common","id":"nemegtosaurus","subtitle":"Sauropod","details":"A Late Cretaceous titanosaur from Mongolia, Nemegtosaurus is known only from a single skull, found in the Nemegt Formation without any trace of the rest of its body.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e5/Nemegtosaurus3.jpg"},{"name":"Rinconsaurus","rarity":"common","id":"rinconsaurus","subtitle":"Sauropod","details":"A Late Cretaceous titanosaur from Argentina, Rinconsaurus was relatively slender and lightly built for its kind, known from the remains of several individuals.","image":"https://upload.wikimedia.org/wikipedia/commons/0/06/Rinconsaurus_test_2_%28for_cladogram%29.jpg"},{"name":"Maxakalisaurus","rarity":"common","id":"maxakalisaurus","subtitle":"Sauropod","details":"A Late Cretaceous titanosaur from Brazil, Maxakalisaurus is one of the country's best-known sauropods, and part of its name was chosen by a public vote of children.","image":"https://images.dinosaurpictures.org/Maxakalisaurus/Maxakalisaurus_3a912d03.jpg"},{"name":"Aegyptosaurus","rarity":"common","id":"aegyptosaurus","subtitle":"Sauropod","details":"A Late Cretaceous sauropod from Egypt, Aegyptosaurus lost its original fossils when they were destroyed by bombing in Munich during the Second World War.","image":"https://images.dinosaurpictures.org/aegyptosaurus_02_7fb0.jpg"},{"name":"Spinophorosaurus","rarity":"common","id":"spinophorosaurus","subtitle":"Sauropod","details":"A Middle Jurassic sauropod from Niger, Spinophorosaurus was an early member of its group that carried paired spikes near the tip of its long, whiplash tail.","image":"https://upload.wikimedia.org/wikipedia/commons/3/37/Spinophorosaurus_NT.jpg"},{"name":"Lusotitan","rarity":"common","id":"lusotitan","subtitle":"Sauropod","details":"A Late Jurassic brachiosaur relative from Portugal, Lusotitan was a large sauropod from the Lourinhã Formation, a coastal landscape rich in dinosaur fossils.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/76/Lusotitan_TD.png/1280px-Lusotitan_TD.png"},{"name":"Parasaurolophus","rarity":"legendary","id":"parasaurolophus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur of western North America, Parasaurolophus wore a long hollow head crest that may have worked like a resonating horn to amplify its calls.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Parasaurolophus_TD.png/1280px-Parasaurolophus_TD.png"},{"name":"Edmontosaurus","rarity":"legendary","id":"edmontosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur of North America, Edmontosaurus is among the best-known duck-billed dinosaurs, with rare fossils preserving skin and other soft tissues.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Edmontosaurus_TD.png/1280px-Edmontosaurus_TD.png"},{"name":"Maiasaura","rarity":"legendary","id":"maiasaura","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from Montana, Maiasaura nested in colonies and cared for its young; its name means 'good mother lizard,' honouring that parental care.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Maiasaura_TD.png/1280px-Maiasaura_TD.png"},{"name":"Lambeosaurus","rarity":"epic","id":"lambeosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from western Canada, Lambeosaurus wore a tall, hatchet-shaped hollow crest, one of the most distinctive head ornaments of any dinosaur.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Lambeosaurus_TD.png/1280px-Lambeosaurus_TD.png"},{"name":"Corythosaurus","rarity":"epic","id":"corythosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from western Canada, Corythosaurus carried a rounded, helmet-like hollow crest rising above its eyes, used for display and calls.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Corythosaurus_TD.png/1280px-Corythosaurus_TD.png"},{"name":"Shantungosaurus","rarity":"epic","id":"shantungosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from China, Shantungosaurus was a giant among duck-billed dinosaurs, ranking among the largest known members of the entire group.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5f/Shantungosaurus_life.png"},{"name":"Iguanodon","rarity":"epic","id":"iguanodon","subtitle":"Hadrosaur","details":"An Early Cretaceous plant-eater from Europe, Iguanodon was famous for its conical thumb spike and was one of the first dinosaurs ever formally named and described.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Iguanodon_TD.png/1280px-Iguanodon_TD.png"},{"name":"Saurolophus","rarity":"epic","id":"saurolophus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur found in Mongolia and North America, Saurolophus carried a short, solid, spike-like crest angled back above its eyes and snout.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Saurolophus_TD.png/1280px-Saurolophus_TD.png"},{"name":"Ouranosaurus","rarity":"epic","id":"ouranosaurus","subtitle":"Hadrosaur","details":"An Early Cretaceous iguanodontian from Niger, Ouranosaurus had tall spines along its back that may have supported a sail or a fatty hump for display or storage.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Ouranosaurus_nigeriensis_restoration.png/1280px-Ouranosaurus_nigeriensis_restoration.png"},{"name":"Hypacrosaurus","rarity":"rare","id":"hypacrosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from western Canada and Montana, Hypacrosaurus is known from embryos through to full-grown adults, tracing its whole life cycle.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e1/Life_reconstruction_of_Hypacrosaurus_altispinus.png"},{"name":"Gryposaurus","rarity":"rare","id":"gryposaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur of western North America, Gryposaurus is recognised by its strongly arched, Roman-style nose, a bold bump rising midway along its snout.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Gryposaurus_TD.png/1280px-Gryposaurus_TD.png"},{"name":"Prosaurolophus","rarity":"rare","id":"prosaurolophus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from western Canada and Montana, Prosaurolophus was a flat-headed duckbill with a small, solid triangular crest in front of its eyes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Prosaurolophus_maximus.png/1280px-Prosaurolophus_maximus.png"},{"name":"Brachylophosaurus","rarity":"rare","id":"brachylophosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from Montana and Canada, Brachylophosaurus had a flat paddle-shaped crest and yielded the famous skin-covered 'mummy' nicknamed Leonardo.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f9/Brachylophosaurus-v4.jpg"},{"name":"Charonosaurus","rarity":"rare","id":"charonosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from the China-Russia border region, Charonosaurus was a large hadrosaur with a long crest much like that of Parasaurolophus.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Charonosaurus-v3_transparent.png/1280px-Charonosaurus-v3_transparent.png"},{"name":"Olorotitan","rarity":"rare","id":"olorotitan","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from the Russian Far East, Olorotitan had a broad, fan-shaped crest that flared out behind its head like an open hand fan.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Olorotitan_TD.png/1280px-Olorotitan_TD.png"},{"name":"Amurosaurus","rarity":"rare","id":"amurosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from the Russia-China border region, Amurosaurus is known from rich bonebeds along the Amur River that held many individuals.","image":"https://upload.wikimedia.org/wikipedia/commons/5/53/Life_reconstruction_of_Amurosaurus_riabinini.png"},{"name":"Tsintaosaurus","rarity":"rare","id":"tsintaosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from China, Tsintaosaurus had a distinctive crest that jutted forward from its forehead like a short, upright spine or small horn.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f3/A_life_reconstruction_of_Tsintaosaurus_spinorhinus.png"},{"name":"Muttaburrasaurus","rarity":"rare","id":"muttaburrasaurus","subtitle":"Hadrosaur","details":"An Early Cretaceous iguanodontian from Australia, Muttaburrasaurus had an enlarged hollow chamber on its nose and is Australia's best-known plant-eating dinosaur.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Muttaburrasaurus_TD.png/1280px-Muttaburrasaurus_TD.png"},{"name":"Hadrosaurus","rarity":"uncommon","id":"hadrosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from New Jersey, Hadrosaurus was the first of its kind named, and the first fairly complete dinosaur skeleton found in North America.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Hadrosaurus_TD.png/1280px-Hadrosaurus_TD.png"},{"name":"Bactrosaurus","rarity":"uncommon","id":"bactrosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur relative from Mongolia and China, Bactrosaurus was an early lambeosaur kin with unusual club-shaped spines on its back vertebrae.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/Bactrosaurus_LM.png/1280px-Bactrosaurus_LM.png"},{"name":"Telmatosaurus","rarity":"uncommon","id":"telmatosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur relative from Romania, Telmatosaurus was a small island dweller that lived on the ancient island of Hațeg in a vanished European sea.","image":"https://upload.wikimedia.org/wikipedia/commons/2/25/Telmatosaurus_sketch_v2.jpg"},{"name":"Tethyshadros","rarity":"uncommon","id":"tethyshadros","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur relative from Italy, Tethyshadros was a small duckbill kin that lived in a coastal island setting on the shores of the ancient Tethys Sea.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Tethyshadros_TD.png/1280px-Tethyshadros_TD.png"},{"name":"Eolambia","rarity":"uncommon","id":"eolambia","subtitle":"Hadrosaur","details":"A Middle Cretaceous plant-eater from Utah, Eolambia stood near the base of the duck-billed family tree, an early member of the lineage that later produced giants.","image":"https://images.dinosaurpictures.org/Eolambia/Eolambia_816afc1f.jpg"},{"name":"Altirhinus","rarity":"uncommon","id":"altirhinus","subtitle":"Hadrosaur","details":"An Early Cretaceous iguanodontian from Mongolia, Altirhinus is named for its tall, arched nose, a deep profile that set it apart from other plant-eaters of its time.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Altirhinus_01_transparent.png/1280px-Altirhinus_01_transparent.png"},{"name":"Mantellisaurus","rarity":"uncommon","id":"mantellisaurus","subtitle":"Hadrosaur","details":"An Early Cretaceous iguanodontian from England and mainland Europe, Mantellisaurus was lightly built and was long classified as a species of its cousin Iguanodon.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Mantellisaurus_TD.png/1280px-Mantellisaurus_TD.png"},{"name":"Velafrons","rarity":"uncommon","id":"velafrons","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from Mexico, Velafrons is known from a young animal whose fan-like crest already rose prominently from the top of its skull.","image":"https://upload.wikimedia.org/wikipedia/commons/8/82/Life_reconstruction_of_Velafrons_coahuilensis.png"},{"name":"Jaxartosaurus","rarity":"uncommon","id":"jaxartosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from Kazakhstan and China, Jaxartosaurus was an early crested duckbill with a low, helmet-like crest crowning its head.","image":"https://upload.wikimedia.org/wikipedia/commons/8/87/Life_reconstruction_of_Jaxartosaurus_aralensis.png"},{"name":"Gilmoreosaurus","rarity":"uncommon","id":"gilmoreosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur relative from Mongolia, Gilmoreosaurus was an early duckbill kin from the Gobi Desert, close to the roots of the great crested lineages.","image":"https://images.dinosaurpictures.org/Gilmoreosaurus/Gilmoreosaurus_25aa1871.jpg"},{"name":"Nipponosaurus","rarity":"uncommon","id":"nipponosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from Sakhalin Island, Nipponosaurus is known from the skeleton of a young animal, a juvenile that still carried a developing crest.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a9/Life_reconstruction_of_Nipponosaurus_sachalinensis.png"},{"name":"Secernosaurus","rarity":"uncommon","id":"secernosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from Argentina, Secernosaurus was one of the first duck-billed dinosaurs named from South America, far from the group's northern heartland.","image":"https://upload.wikimedia.org/wikipedia/commons/9/96/Secernosaurus_koerneri.png"},{"name":"Ajnabia","rarity":"uncommon","id":"ajnabia","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from Morocco, Ajnabia was a small duck-billed dinosaur and among the first of its kind ever found on the African continent.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b5/Life_reconstruction_of_Ajnabia_odysseus.png"},{"name":"Sirindhorna","rarity":"uncommon","id":"sirindhorna","subtitle":"Hadrosaur","details":"An Early Cretaceous iguanodontian relative from Thailand, Sirindhorna is known mainly from skull material, which showed a distinctive crest along its head.","image":"https://images.dinosaurpictures.org/Sirindhorna/Sirindhorna_77fbae67.jpg"},{"name":"Fukuisaurus","rarity":"uncommon","id":"fukuisaurus","subtitle":"Hadrosaur","details":"An Early Cretaceous iguanodontian relative from Japan, Fukuisaurus came from the rich dinosaur quarries of Fukui, a prefecture famous for its fossil discoveries.","image":"https://images.dinosaurpictures.org/Fukuisaurus-Andrey-Atuchin_30b2.jpg"},{"name":"Acristavus","rarity":"common","id":"acristavus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from Montana and Utah, Acristavus had no crest at all; its name means 'crestless grandfather,' marking an early unadorned duckbill.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f6/Acristavus_gagslarsoni.png"},{"name":"Adelolophus","rarity":"common","id":"adelolophus","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from Utah, Adelolophus is known from a partial skull and ranks among the oldest named crested duckbills from North America.","image":"https://upload.wikimedia.org/wikipedia/commons/9/95/Life_reconstruction_of_Adelolophus_hutchisoni.png"},{"name":"Aralosaurus","rarity":"common","id":"aralosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from Kazakhstan, Aralosaurus carried a low bump of a crest in front of its eyes, a modest ornament compared with its showier cousins.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f4/Life_reconstruction_of_Aralosaurus_tuberiferus.png"},{"name":"Arenysaurus","rarity":"common","id":"arenysaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from Spain, Arenysaurus was among the last dinosaurs living in Europe, surviving in the foothills of what became the Pyrenees.","image":"https://upload.wikimedia.org/wikipedia/commons/8/89/Life_reconstruction_of_Arenysaurus_ardevoli.png"},{"name":"Bonapartesaurus","rarity":"common","id":"bonapartesaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from Argentina, Bonapartesaurus was a South American duckbill with unusually tall spines running along its back and tail.","image":"https://upload.wikimedia.org/wikipedia/commons/3/36/Bonapartesaurus_rionegrensis.png"},{"name":"Canardia","rarity":"common","id":"canardia","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from France, Canardia was a small crested duckbill that lived in the foothills of the Pyrenees near the end of the dinosaur age.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b2/Life_reconstruction_of_Canardia_garonnensis.png"},{"name":"Cedrorestes","rarity":"common","id":"cedrorestes","subtitle":"Hadrosaur","details":"An Early Cretaceous duck-billed relative from Utah, Cedrorestes is known mainly from its hip bones, an early hint of the great hadrosaur radiation to come.","image":"https://images.dinosaurpictures.org/Cedrorestes/Cedrorestes_92b22baa.jpg"},{"name":"Claosaurus","rarity":"common","id":"claosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from Kansas, Claosaurus was preserved in chalk deposited on the floor of the ancient Western Interior Seaway that once covered the plains.","image":"https://images.dinosaurpictures.org/Claosaurus/Claosaurus_4884c0cc.jpg"},{"name":"Eotrachodon","rarity":"common","id":"eotrachodon","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from Alabama, Eotrachodon is a rare duck-billed dinosaur from Appalachia, the forested eastern landmass of ancient North America.","image":"https://upload.wikimedia.org/wikipedia/commons/7/76/Eotrachodon_NT_small_transparent.png"},{"name":"Equijubus","rarity":"common","id":"equijubus","subtitle":"Hadrosaur","details":"An Early Cretaceous duck-billed relative from China, Equijubus was among the first members of this herbivorous lineage to be recognised from Asia.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Equijubus_TD.png/1280px-Equijubus_TD.png"},{"name":"Gongpoquansaurus","rarity":"common","id":"gongpoquansaurus","subtitle":"Hadrosaur","details":"An Early Cretaceous basal duck-billed relative from Gansu Province, China, Gongpoquansaurus helps trace how hadrosaurs began their rise in Asia.","image":"https://dinodata.de/images/dinosaurs/dino_g/%7Egongpoquansaurus/Gongpoquansaurus-by-eloymanzanero.webp"},{"name":"Huehuecanauhtlus","rarity":"common","id":"huehuecanauhtlus","subtitle":"Hadrosaur","details":"A Late Cretaceous duck-billed dinosaur from Mexico, Huehuecanauhtlus was a southern North American member of the hadrosaur lineage of plant-eaters.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/Huehuecanauhtlus_tiquichensis_copia.jpg/1280px-Huehuecanauhtlus_tiquichensis_copia.jpg"},{"name":"Kazaklambia","rarity":"common","id":"kazaklambia","subtitle":"Hadrosaur","details":"A Late Cretaceous lambeosaur from Kazakhstan, Kazaklambia is a Central Asian crested hadrosaur known mainly from the skeleton of a young animal.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d6/Life_reconstruction_of_Kazaklambia_convincens.png"},{"name":"Kerberosaurus","rarity":"common","id":"kerberosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from the Amur region of Russia, Kerberosaurus was a duck-billed herbivore closely related to the crested Saurolophus.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0c/Kerberosaurus_manakini.png"},{"name":"Latirhinus","rarity":"common","id":"latirhinus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from Mexico, Latirhinus was a flat-headed duck-billed herbivore distinguished by its unusually broad, flattened nose.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5e/Life_reconstruction_of_Latirhinus_uitstlani.png"},{"name":"Levnesovia","rarity":"common","id":"levnesovia","subtitle":"Hadrosaur","details":"A Late Cretaceous duck-billed relative from Uzbekistan, Levnesovia lived in Central Asia as hadrosaurs spread widely across the northern continents.","image":"https://images.dinosaurpictures.org/Levnesovia/levnesovia_by_cisiopurple_daiblaj-fullview_e5a6.jpg"},{"name":"Naashoibitosaurus","rarity":"common","id":"naashoibitosaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous hadrosaur from New Mexico, Naashoibitosaurus was a flat-headed duckbill with a low, curved crest set just in front of its eyes.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5e/Naashoibitosaurus_ostromi.png"},{"name":"Penelopognathus","rarity":"common","id":"penelopognathus","subtitle":"Hadrosaur","details":"An Early Cretaceous primitive duck-billed relative from Mongolia, Penelopognathus is known from jaw material that hints at the early hadrosaur body plan.","image":"https://images.dinosaurpictures.org/Penelopognathus/Penelopognathus_03ca6629.jpg"},{"name":"Protohadros","rarity":"common","id":"protohadros","subtitle":"Hadrosaur","details":"A mid-Cretaceous early duck-billed relative from Texas, Protohadros was once thought to be the oldest hadrosaur known, with a deep, down-turned jaw.","image":"https://images.dinosaurpictures.org/Protohadros_0f9b.jpg"},{"name":"Tanius","rarity":"common","id":"tanius","subtitle":"Hadrosaur","details":"A Late Cretaceous flat-headed hadrosaur from China, Tanius was among the first dinosaurs named from that country and was a large duck-billed herbivore.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/Tanius_transparent.png/500px-Tanius_transparent.png"},{"name":"Wulagasaurus","rarity":"common","id":"wulagasaurus","subtitle":"Hadrosaur","details":"A Late Cretaceous flat-headed hadrosaur from Heilongjiang, China, Wulagasaurus came from bonebeds near the Amur River in the far northeast of Asia.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e6/Wulagasaurus_dongi.png"},{"name":"Xuwulong","rarity":"common","id":"xuwulong","subtitle":"Hadrosaur","details":"An Early Cretaceous duck-billed relative from China, Xuwulong had an unusually short skull for its lineage, ending in a broad, U-shaped beak.","image":"https://upload.wikimedia.org/wikipedia/commons/5/56/Xuwulong_NT_flipped_transparent.png"}]});
